def lesson_goal(title, course_id, n):
    t=title.lower()
    specific=[
    (['тайский без паники','старт','с чего начать'],'Понять базовую логику курса и выучить первый небольшой набор фраз для безопасного старта.'),
    (['знакомство','знакомства','я и ты','он, она','семья','возраст','мой, твой','друзья','гости'],'Научиться сообщать, кто вы, кто рядом, чей это предмет и поддержать короткое знакомство.'),
    (['как дела','эмоции','чувства'],'Научиться спросить о состоянии, ответить о себе и выразить простую эмоцию в бытовом контексте.'),
    (['просьб','сделай','уберите','почините','можно пораньше','подождите'],'Научиться сформулировать вежливую просьбу, уточнить возможность и поблагодарить за действие.'),
    (['где тут','прямо','налево','направо','метров','ориентир'],'Научиться спросить или дать простое направление с ориентиром и расстоянием.'),
    (['цена','сколько','деньги','оплата','банк','крипта','счёт'],'Научиться спросить стоимость/счёт, уточнить способ оплаты и подтвердить договорённость.'),
    (['спасибо','извини','до свидания','прощан','благодар'],'Научиться корректно завершить бытовой контакт, поблагодарить или извиниться.'),
    (['тон','интонац','падение','подъём','быстрая речь','каа','кхрап','май пэн рай','джай','крэнг'],'Научиться распознавать и использовать выбранную произносительную/разговорную особенность на знакомых фразах.'),
    (['числа','время','дни','который час','раз'],'Научиться назвать число/время/день и использовать его в коротком бытовом запросе.'),
    (['глагол','идти','приходить','хотеть','любить','говорить','понимать','есть','пить','покупать','делать','работать','спать','сидеть','давать','знать','видеть','жить'],'Научиться использовать ключевую конструкцию в нескольких простых фразах о действии, желании или состоянии.'),
    (['вкусно','остро','красиво','горячо','холодно','большой','маленький','хороший','плохой','новый','старый','быстрый','дорого'],'Научиться описать предмет/еду и выразить простую оценку, сравнение или предпочтение.'),
    (['такси','таксист','аэропорт','счётчик','grab'],'Научиться назвать пункт назначения, уточнить цену/счётчик, дать направление или попросить остановиться.'),
    (['рынок','магазин','7-eleven','кафе','еда','пиво','счёт'],'Научиться выбрать товар/блюдо, спросить цену или состав, уточнить заказ и оплатить.'),
    (['полици','пост','паспорт','виза','иммиграц','документ'],'Научиться спокойно ответить на базовые административные вопросы, показать документ и попросить уточнение.'),
    (['доктор','медицин','врач','страхов','помощь','срочн'],'Научиться сообщить базовую проблему, место/срочность, попросить помощь и понять простой ответ.'),
    (['кондо','дом','хозяин','сосед','правила','кондиционер','сервис'],'Научиться описать бытовую проблему/правило, договориться о действии или времени и завершить разговор.'),
    (['достав','курьер','адрес','таиланд доставляет'],'Научиться передать адрес и ориентир, объяснить место встречи, получить заказ и решить проблему со звонком.'),
    (['работ','коллег','статус','small talk','комплимент'],'Научиться попросить о рабочем действии, уточнить статус/срок и поддержать короткий разговор.'),
    (['конфликт','резк','мягк','понятн','без давления','сервис','скрытые смыслы'],'Научиться выразить просьбу, несогласие или исправление мягко и понятно, не усиливая конфликт.'),
    (['блог','хобби','движ','ретрит','романтик','дет','мем','юмор','поп-культур','сонгкран','пляж','вечер','музык','танц'],'Научиться поддержать короткий разговор в данном социальном/культурном контексте и выразить своё намерение.'),
    (['виза','иммиграц','продлен'],'Научиться уточнить документы, срок, очередь и следующий административный шаг.'),
    (['питом','ветерин'],'Научиться описать состояние питомца, попросить услугу и уточнить дальнейшие действия.'),
    ]
    for keys,goal in specific:
        if any(k in t for k in keys): return goal
    if 'сценк' in t or 'диалог' in t or 'сборный' in t:
        return 'Собрать лексику текущего блока в короткий бытовой диалог от начала ситуации до её завершения.'
    return 'Выучить ключевые карточки темы и уметь использовать их в одной понятной бытовой ситуации.'

rows=list(csv.DictReader(open('course_lesson_inventory.tsv',encoding='utf-8'),delimiter='\t'))
by={}
for r in rows: by.setdefault(r['course_id'],[]).append(r)
lines=['# Цели курсов и уроков: «как сейчас → как предлагаем»','', 'Это draft редакторской таблицы. Исходные JSON и main branch не изменяются. «Как сейчас» — текущие названия и фактическая структура. «Как предлагаем» — цель, которую нужно проверить перед внесением правок.', '', '## Course-level table','', '| ID | Как сейчас: блок и название | Уроков | Как предлагаем: цель курса |', '|---|---|---:|---|']
for cid,(block,title,goal) in course_goals.items():
    lines.append(f'| `{cid}` | {block}: **{title}** | {len(by.get(cid,[]))} | {goal} |')
lines += ['', '## Lesson-level tables','', 'В колонке «как сейчас» сохраняется существующий title. Предлагаемая формулировка не означает автоматическое переписывание карточек: это редакторский outcome, по которому затем проверяется состав steps.', '']
for cid,(block,ctitle,cgoal) in course_goals.items():
    lines += [f'### `{cid}` — {ctitle}', '', '| Lesson | Как сейчас | Steps | Как предлагаем: outcome урока |', '|---|---|---:|---|']
    for r in by.get(cid,[]):
        lines.append(f"| `{r['lesson_id']}` | {r['lesson_title']} | {r['record_count'] or '—'} | {lesson_goal(r['lesson_title'],cid,r['lesson_id'])} |")
    lines.append('')
lines += ['## Как использовать таблицу', '', 'Сначала согласовываются course outcomes. Затем по каждому уроку проверяется, действительно ли его steps дают заявленный outcome. Если нет, карточки не переписываются автоматически: их классифицируем как оставить, переместить, объединить, заменить или добавить.', '', 'До явного OK пользователя изменения в основной ветке и в production data не вносятся.']
Path('curriculum_goals_table_draft_ru.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('courses',len(course_goals),'lessons',sum(len(v) for v in by.values()))
